		LmdbLiteral left = new LmdbLiteral(leftRevision, "equal", ID);
		LmdbLiteral right = new LmdbLiteral(rightRevision, "equal", OTHER_ID);
		assertTrue(left.equals(right));
		assertEquals(ID, left.getInternalID());
		assertEquals(OTHER_ID, right.getInternalID());
