	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void sharesIdAfterLazyResolutionAndPreservesCachedHashes(boolean inline, @TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(inline).setValueHashCacheEnabled(true);
		ValueStore store = new ValueStore(directory.toFile(), config);
		try {
			Literal term = inline ? VF.createLiteral("42", CoreDatatype.XSD.INTEGER)
					: VF.createLiteral("non-inlined literal for lazy equality");
			store.startTransaction(true);
			long id = store.storeValue(term);
			store.commit();
			assertEquals(inline, ValueIds.isInlined(id));

			for (boolean receiverKnown : new boolean[] { false, true }) {
				LmdbLiteral unknown = literal(store.createLiteral("revision").getValueStoreRevision(), term,
						LmdbValue.UNKNOWN_ID);
				LmdbLiteral lazy = new LmdbLiteral(new ValueStoreRevision.Lazy(unknown.getValueStoreRevision()), id);
				assertInstanceOf(ValueStoreRevision.Lazy.class, lazy.getValueStoreRevision());
				assertFalse(lazy.isInitialized());
				int hash = unknown.hashCode();

				assertTrue(receiverKnown ? lazy.equals(unknown) : unknown.equals(lazy));
				assertEquals(id, unknown.getInternalID());
				assertEquals(id, lazy.getInternalID());
				assertTrue(lazy.isInitialized());
				assertSame(unknown.getValueStoreRevision(), lazy.getValueStoreRevision());
				assertEquals(hash, unknown.hashCode());
				assertEquals(hash, lazy.hashCode());
				assertEquals(term, unknown);
			}
		} finally {
			store.close();
		}
	}

