	@Test
	void customDatatypeIdsAndLiteralIdsShareIndependently() {
		ValueStoreRevision revision = new ValueStoreRevision.Default(null);
		LmdbIRI unknownDatatype = new LmdbIRI(revision, "urn:datatype:custom");
		LmdbIRI knownDatatype = new LmdbIRI(revision, "urn:datatype:custom", ValueIds.createId(ValueIds.T_URI, 3));
		LmdbLiteral unknown = new LmdbLiteral(revision, "equal", unknownDatatype);
		LmdbLiteral known = new LmdbLiteral(revision, "equal", knownDatatype, ID);

		assertTrue(unknown.equals(known));
		assertEquals(ID, unknown.getInternalID());
		assertEquals(knownDatatype.getInternalID(), unknownDatatype.getInternalID());
		assertEquals(CoreDatatype.NONE, unknown.getCoreDatatype());
	}

	private static LmdbLiteral literal(ValueStoreRevision revision, Literal term, long id) {
		return term.getLanguage().isPresent()
				? new LmdbLiteral(revision, term.getLabel(), term.getLanguage().orElseThrow(), term.getBaseDirection(),
						id)
				: new LmdbLiteral(revision, term.getLabel(), term.getDatatype(), term.getCoreDatatype(), id);
	}

	private static final class CountingLiteral extends LmdbLiteral {

		private int termReads;

		private CountingLiteral(ValueStoreRevision revision, long id) {
			super(revision, "equal", id);
		}

		@Override
		public String getLabel() {
			termReads++;
			return super.getLabel();
		}

		@Override
		public Optional<String> getLanguage() {
			termReads++;
			return super.getLanguage();
		}
	}

	private static final class StoreRevision extends ValueStoreRevision.Base {

		private final ValueStore store;

		private StoreRevision(ValueStore store) {
			this.store = store;
		}

		@Override
		public long getRevisionId() {
			return 1;
		}

		@Override
		public ValueStore getValueStore() {
			return store;
		}

		@Override
		public boolean resolveValue(long id, LmdbValue value) {
			return store.resolveValue(id, value);
		}
	}
